// Pages publiques, sites des entreprises et espace pro. Tous les textes passent par t() (clé = français).
import { esc, phoneFmt } from './util.js';
import { PLANS, planHas, config } from './config.js';
import { TEMPLATES, tplLabel, templateFor } from './templates.js';
import { KB } from './support.js';
import { t, currentLang, LANGS, fmtTime, fmtDay, dayName, fmtDate, locale } from './i18n.js';
import { COUNTRIES, countryName, priceOf, money, ALL_TZ, CURRENCIES } from './markets.js';

const FONT = '<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800;900&display=swap" rel="stylesheet">';
export function layout(title, body, { bodyClass = '', brand = null, head = '', lang = null } = {}) {
  const style = brand ? `<style>:root{--brand:${/^#[0-9a-f]{6}$/i.test(brand) ? brand : '#ffcf33'}}</style>` : '';
  const env = config.appEnv === 'staging' ? `<div class="env-bar" role="note">${t('ENVIRONNEMENT DE TEST : paiements fictifs, aucun message envoyé aux vrais clients')}</div>` : '';
  return `<!DOCTYPE html><html lang="${lang || currentLang()}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#14161a"><title>${esc(title)}</title>${FONT}<link rel="stylesheet" href="/static/app.css">${style}${head}</head><body class="${bodyClass}">${env}${body}</body></html>`;
}
export const csrfField = (s) => `<input type="hidden" name="csrf" value="${esc(s)}">`;
export const flash = (m, kind = 'ok') => (m ? `<div class="flash ${kind}" role="status">${esc(m)}</div>` : '');
const errs = (list) => (list && list.length ? `<div class="flash err" role="alert">${list.map(esc).join('<br>')}</div>` : '');
export const STATUS_LABEL = { demo: 'Démo', trial: 'Essai', active: 'Actif', past_due: 'Impayé', paused: 'En pause', canceled: 'Résilié' };
const st = (s) => t(STATUS_LABEL[s] || s);
const planName = (k) => t(PLANS[k].name);
const loc = (c = null) => locale(currentLang(), c);
/** Prix d'une formule dans une devise, formaté. */
const price = (plan, cur) => { const p = priceOf(plan, cur); return { m: money(p.monthly, p.currency, loc()), s: money(p.setup, p.currency, loc()) }; };
const langSwitch = (path = '/') => `<span class="langs">${Object.keys(LANGS).map((l) => (l === currentLang() ? `<b>${l.toUpperCase()}</b>` : `<a href="${esc(path)}?lang=${l}" hreflang="${l}" lang="${l}">${l.toUpperCase()}</a>`)).join(' ')}</span>`;
const FOOT = () => `<footer class="foot"><div class="wrap row"><span>ClientDirect Pro · ${t('Un service de {n}', { n: esc(config.legal.name) })}</span><span><a href="/exemples">${t('Exemples')}</a> · <a href="/metiers">${t('Métiers')}</a> · <a href="/partenaires">${t('Partenaires')}</a> · <a href="/annuaire">${t('Annuaire des sites')}</a> · <a href="/cgu">${t('Conditions')}</a> · <a href="/confidentialite">${t('Confidentialité')}</a> · <a href="/mentions-legales">${t('Mentions légales')}</a> · <a href="/connexion">${t('Espace pro')}</a></span></div></footer>`;
const ICON = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true" class="ic"><path d="M5 12.5l4.2 4.2L19 7" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  no: '<svg viewBox="0 0 24 24" aria-hidden="true" class="ic no"><path d="M7 12h10" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>'
};

// ---------- page d'accueil commerciale ----------
const FEATURES = [ // [clé de fonctionnalité, libellé]
  ['site', 'Site professionnel à votre nom, sur mobile et ordinateur'], ['whatsapp', 'Bouton WhatsApp et appel direct'], ['devis', 'Demandes de devis reçues par e-mail'],
  ['rdv', 'Prise de rendez-vous en ligne, sans double réservation'], ['rappels', 'Confirmations et rappels automatiques (e-mail, WhatsApp)'], ['dashboard', 'Tableau de bord, statistiques et bilan mensuel'],
  ['domaine', 'Votre propre nom de domaine (www.votre-entreprise.com)'], ['ia', 'Assistant IA 24 h/24 qui répond et réserve pour vous']
];
const has = (plan, f) => (f === 'domaine' ? planHas(plan, 'rdv') : planHas(plan, f));
const IDEAL = { essentiel: 'Pour être trouvé et contacté facilement', pro: 'Pour remplir son agenda sans y passer de temps', premium: 'Pour ne plus manquer aucun client, même la nuit' };
export function planCards(cur, { action = null, csrf = '', current = null, disabled = false } = {}) {
  return `<div class="plans">${Object.keys(PLANS).map((k) => {
    const p = price(k, cur); const best = k === 'pro';
    const cta = action ? `<form method="post" action="${action}">${csrfField(csrf)}<input type="hidden" name="plan" value="${k}"><button class="btn ${current === k || best ? 'blue' : 'ghost'} wide" type="submit" ${disabled ? 'disabled' : ''}>${t('Choisir {p}', { p: planName(k) })}</button></form>` : `<a class="btn ${best ? 'blue' : 'ghost'} wide" href="/inscription?formule=${k}">${t('Essayer gratuitement')}</a>`;
    return `<div class="plan ${best ? 'best' : ''}">${best ? `<span class="ribbon">${t('Le plus choisi')}</span>` : ''}<h3>${planName(k)}</h3><p class="ideal">${t(IDEAL[k])}</p><div class="price">${p.m}<small> ${t('HT / mois')}</small></div><p class="muted small">${t('+ {s} HT de mise en service, une seule fois', { s: p.s })}</p>
      <ul class="feat">${FEATURES.filter(([f]) => has(k, f)).map(([, l]) => `<li>${ICON.check}<span>${t(l)}</span></li>`).join('')}</ul>${FEATURES.some(([f]) => !has(k, f)) ? `<p class="feat-off-title">${t('Non inclus')}</p><ul class="feat off-list">${FEATURES.filter(([f]) => !has(k, f)).map(([, l]) => `<li class="off">${ICON.no}<span>${t(l)}</span></li>`).join('')}</ul>` : `<p class="feat-all">${ICON.check}<span>${t('Toutes les fonctionnalités incluses')}</span></p>`}${cta}</div>`;
  }).join('')}</div>`;
}
function compareTable(cur) {
  const rows = FEATURES.map(([f, l]) => `<tr><th scope="row">${t(l)}</th>${Object.keys(PLANS).map((k) => `<td>${has(k, f) ? `${ICON.check}<span class="sr">${t('Inclus')}</span>` : `${ICON.no}<span class="sr">${t('Non inclus')}</span>`}</td>`).join('')}</tr>`).join('');
  return `<div class="scroll"><table class="compare"><caption class="sr">${t('Comparatif des formules')}</caption><thead><tr><th></th>${Object.keys(PLANS).map((k) => `<th scope="col">${planName(k)}<br><span class="muted">${price(k, cur).m}${t('/mois')}</span></th>`).join('')}</tr></thead><tbody>${rows}
  <tr><th scope="row">${t('Nombre de postes ou employés')}</th><td>—</td><td>${t('Illimité')}</td><td>${t('Illimité')}</td></tr><tr><th scope="row">${t('Mise en service (une fois)')}</th>${Object.keys(PLANS).map((k) => `<td>${price(k, cur).s}</td>`).join('')}</tr></tbody></table></div>`;
}
const FAQ = [
  ['Combien de temps pour avoir mon site ?', 'Environ 5 minutes. Vous choisissez votre métier, le site est créé avec des prestations, des tarifs et des horaires que vous modifiez ensuite en un clic.'],
  ['Faut-il une carte bancaire pour essayer ?', 'Non. L’essai de 14 jours est gratuit et sans carte. Vous ne payez que si vous décidez de continuer.'],
  ['Y a-t-il un engagement ?', 'Après l’essai, l’abonnement est mensuel avec un engagement de 12 mois. Les frais de mise en service sont payés une seule fois.'],
  ['Je ne suis pas à l’aise avec l’informatique.', 'Tout se gère depuis votre téléphone : vous recevez les demandes, vous confirmez d’un bouton. L’aide répond à vos questions et un ticket est traité par une personne si besoin.'],
  ['Mes clients doivent-ils créer un compte ?', 'Non. Ils choisissent un créneau, laissent leur nom et leur téléphone, et reçoivent la confirmation.'],
  ['Que deviennent mes données ?', 'Elles sont hébergées en Europe, sauvegardées et chiffrées plusieurs fois par jour. Vous pouvez les télécharger ou les supprimer à tout moment.'],
  ['Dans quels pays puis-je l’utiliser ?', 'Partout : les sites s’affichent dans votre langue, votre devise et votre fuseau horaire. Le paiement de l’abonnement s’ouvre pays par pays.']
];
