// ---------- authentification ----------
export function signupPage({ csrf, f = {}, errors = [], claim = null, demo = null }) {
  const lang = currentLang();
  const tplOpts = Object.keys(TEMPLATES).map((k) => `<option value="${k}" ${f.tpl === k ? 'selected' : ''}>${esc(tplLabel(k, lang))}</option>`).join('');
  const cOpts = Object.keys(COUNTRIES).map((k) => [k, countryName(k, lang)]).sort((a, b) => (a[0] === 'OTHER') - (b[0] === 'OTHER') || a[1].localeCompare(b[1], lang)).map(([k, n]) => `<option value="${k}" ${f.country === k ? 'selected' : ''}>${esc(n)}</option>`).join('');
  const cur = f.currency || COUNTRIES[f.country]?.cur || 'EUR';
  const planOpts = Object.keys(PLANS).map((k) => `<option value="${k}" ${(f.plan || 'pro') === k ? 'selected' : ''}>${planName(k)} (${t('{p}/mois après l’essai', { p: price(k, cur).m })})</option>`).join('');
  return layout(t('Créer mon site'), `<main class="auth"><a class="logo" href="/">ClientDirect Pro</a><h1>${demo ? t('Activer le site de {n}', { n: esc(demo.name) }) : t('Créer mon site')}</h1><p class="muted">${t('Essai gratuit de {d} jours, sans carte bancaire.', { d: config.trialDays })}</p>${errs(errors)}
  <form method="post" action="/inscription" class="card" id="signup" novalidate>${csrfField(csrf)}${claim ? `<input type="hidden" name="claim" value="${esc(claim)}">` : ''}<input type="hidden" name="tz" id="tz" value="${esc(f.tz || '')}"><input type="hidden" name="lang" value="${esc(f.lang || lang)}">
  ${demo ? '' : `<label for="business">${t('Nom de l’entreprise')}</label><input id="business" name="business" required maxlength="80" value="${esc(f.business)}">
  <div class="g2"><div><label for="tpl">${t('Métier')}</label><select id="tpl" name="tpl">${tplOpts}</select></div><div><label for="city">${t('Ville')}</label><input id="city" name="city" maxlength="60" value="${esc(f.city)}"></div></div>
  <div class="g2"><div><label for="country">${t('Pays')}</label><select id="country" name="country">${cOpts}</select></div><div><label for="phone">${t('Téléphone WhatsApp')}</label><input id="phone" name="phone" type="tel" autocomplete="tel" value="${esc(f.phone)}"></div></div>`}
  <label for="plan">${t('Formule')}</label><select id="plan" name="plan">${planOpts}</select>
  <label for="name">${t('Votre nom')}</label><input id="name" name="name" autocomplete="name" required maxlength="80" value="${esc(f.name)}">
  <label for="email">${t('E-mail')}</label><input id="email" name="email" type="email" autocomplete="email" required value="${esc(f.email)}">
  <label for="password">${t('Mot de passe (10 caractères minimum, lettres et chiffres)')}</label><input id="password" name="password" type="password" autocomplete="new-password" required minlength="10">
  <label class="ck"><input type="checkbox" name="cgu" ${f.cgu ? 'checked' : ''}> <span>${t('J’accepte les <a href="/cgu" target="_blank" rel="noopener">conditions d’utilisation</a> (dont l’accord de sous-traitance des données) et la <a href="/confidentialite" target="_blank" rel="noopener">politique de confidentialité</a>')}</span></label>
  <button class="btn blue wide" type="submit">${t('Créer mon site')}</button></form><p class="muted">${t('Déjà inscrit ?')} <a href="/connexion">${t('Connexion')}</a> · ${langSwitch('/inscription')}</p></main><script src="/static/signup.js" defer></script>`);
}
export const loginPage = ({ csrf, error = '', email = '', info = '' }) => layout(t('Connexion'), `<main class="auth"><a class="logo" href="/">ClientDirect Pro</a><h1>${t('Connexion')}</h1>${flash(info)}${error ? `<div class="flash err" role="alert">${esc(error)}</div>` : ''}
  <form method="post" action="/connexion" class="card">${csrfField(csrf)}<label for="email">${t('E-mail')}</label><input id="email" name="email" type="email" autocomplete="email" required value="${esc(email)}"><label for="password">${t('Mot de passe')}</label><input id="password" name="password" type="password" autocomplete="current-password" required><button class="btn blue wide" type="submit">${t('Se connecter')}</button></form>
  <p class="muted"><a href="/mot-de-passe-oublie">${t('Mot de passe oublié ?')}</a> · <a href="/inscription">${t('Créer un compte')}</a> · ${langSwitch('/connexion')}</p></main>`);
export const totpPage = ({ csrf, error = '' }) => layout(t('Double authentification'), `<main class="auth"><h1>${t('Double authentification')}</h1>${error ? `<div class="flash err" role="alert">${esc(error)}</div>` : ''}
  <form method="post" action="/connexion/2fa" class="card">${csrfField(csrf)}<label for="code">${t('Code à 6 chiffres')}</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required><button class="btn blue wide" type="submit">${t('Valider')}</button></form></main>`);
