// ---------- site d'une entreprise ----------
const NOTICE = (tn) => `<p class="note small">${t('Vos coordonnées servent uniquement à {n} pour traiter votre demande (rendez-vous, devis, confirmation et rappel). Elles sont conservées {m} mois au plus. Vous pouvez y accéder, les corriger ou les faire supprimer en contactant {n}.', { n: esc(tn.name), m: config.retentionCustomerMonths })} <a href="${esc(config.baseUrl)}/confidentialite" target="_blank" rel="noopener">${t('En savoir plus')}</a></p>`;
/** Textes utilisés par le script du site (navigateur du client). */
const siteStrings = () => JSON.stringify(Object.fromEntries(['Chargement…', 'Aucun jour disponible.', 'Plus de créneau libre ce jour-là. Choisissez un autre jour.', 'Choisissez une heure.', 'Réservation impossible, réessayez.', 'Connexion impossible. Vérifiez votre réseau et réessayez.', 'Envoi impossible, réessayez.', 'Je n’ai pas compris, reformulez votre question.', 'Connexion impossible. Réessayez.'].map((k) => [k, t(k)]))).replace(/</g, '\\u003c');
export function tenantSite(tn, { base, mode = 'live', days = [], aiMode = 'simple', demoClaim = null, head = '' }) {
  const lang = currentLang(); const today = new Date().getDay();
  const money2 = (v) => money(v, tn.currency || 'EUR', locale(lang, tn.country));
  const svcCards = tn.services.map((s) => `<div class="svc"><h3>${esc(s.name)}</h3><p class="muted">${esc(s.descr)}</p><b class="price-r">${s.price > 0 ? t('à partir de {p}', { p: money2(s.price) }) : t('Sans frais')}</b><span class="muted">${t('Durée : {d} min', { d: s.dur })}</span></div>`).join('');
  const opts = tn.services.map((s) => `<option value="${s.id}">${esc(s.name)}</option>`).join('');
  const hours = [1, 2, 3, 4, 5, 6, 0].map((d) => `<tr${d === today ? ' class="today"' : ''}><td>${dayName(d)}</td><td>${tn.hours[d] ? `${fmtTime(tn.hours[d][0])} – ${fmtTime(tn.hours[d][1])}` : t('Fermé')}</td></tr>`).join('');
  const wa = tn.phone ? `${base}/wa` : null;
  const banner = mode === 'demo' ? `<div class="demo-bar"><b>${t('Démonstration non officielle')}</b> · ${t('préparée par ClientDirect Pro, sans lien avec {n}. Les prestations, prix et horaires sont des exemples. Rien n’est enregistré.', { n: esc(tn.name) })} <a class="btn sm blue" href="/inscription?claim=${esc(demoClaim)}">${t('Activer ce site')}</a></div>`
    : mode === 'example' ? `<div class="demo-bar"><b>${t('Site d’exemple fictif')}</b><span class="sep"> · </span>${t('Testez la réservation, le devis et l’assistant : rien n’est enregistré.')} <a class="btn sm blue" href="/inscription?tpl=${esc(tn.tpl)}">${t('Créer le mien')}</a></div>` : '';
  const booking = planHas(tn.plan, 'rdv') ? `<div class="card" id="rdv"><h3>${esc(tn.verb)}</h3><p class="muted">${tn.auto_confirm ? t('Confirmation immédiate.') : t('Le professionnel confirme votre rendez-vous.')} ${t('Seuls les créneaux libres sont proposés.')}</p>
    <form id="book" data-base="${esc(base)}" data-lang="${lang}" novalidate><label for="b-svc">${t('Prestation')}</label><select id="b-svc" name="serviceId">${opts}</select>
    <label>${t('Jour')}</label><div class="days" id="b-days" role="group" aria-label="${t('Jour')}">${days.map((d, i) => `<button type="button" class="chip" data-d="${d}" aria-pressed="${i === 0}">${esc(fmtDay(d))}</button>`).join('')}</div>
    <label>${t('Heure')}</label><div class="slots" id="b-slots" role="group" aria-label="${t('Heure')}"><p class="muted">${t('Chargement…')}</p></div>
    <div class="g2"><div><label for="b-name">${t('Nom')}</label><input id="b-name" name="name" autocomplete="name" required></div><div><label for="b-phone">${t('Téléphone')}</label><input id="b-phone" name="phone" type="tel" autocomplete="tel" required></div></div>
    <label for="b-email">${t('E-mail (pour recevoir la confirmation)')}</label><input id="b-email" name="email" type="email" autocomplete="email">
    <div class="err" id="b-err" role="alert"></div><button class="btn red wide" type="submit">${tn.auto_confirm ? t('Réserver') : t('Demander ce créneau')}</button><div id="b-ok" role="status"></div>${NOTICE(tn)}</form></div>` : '';
  return layout(tn.name, `${banner}<section class="hero band"><div class="wrap hgrid"><div><h1>${esc(tn.name)}</h1><p class="sub">${esc(tn.metier)}${tn.city ? ` · ${esc(tn.city)}` : ''}</p><p class="lead">${esc(tn.lead)}</p>
    <div class="cta">${planHas(tn.plan, 'rdv') ? `<a class="btn red" href="#rdv">${t('Prendre rendez-vous')}</a>` : ''}<a class="btn ghost-dark" href="#devis">${t('Demander un devis')}</a>${wa ? `<a class="btn wa" href="${esc(wa)}" rel="noopener">WhatsApp</a>` : ''}</div></div>
    <div class="chat" id="chat" data-base="${esc(base)}"><div class="chat-top"><b>${t('Assistant de {n}', { n: esc(tn.name) })}</b><span>${aiMode === 'ia' ? t('Assistant IA · répond et réserve') : t('Réponses automatiques')}</span></div><div class="msgs" id="msgs" aria-live="polite"><div class="m">${t('Bonjour ! Posez votre question sur nos prestations, tarifs ou horaires.')}</div></div><form class="ask" id="ask"><input id="q" aria-label="${t('Votre question')}" placeholder="${t('Votre question…')}" maxlength="600" autocomplete="off"><button class="btn sm" type="submit">${t('Envoyer')}</button></form></div></div></section>
  <div class="stripe" aria-hidden="true"></div>
  <section class="band"><div class="wrap"><h2>${t('Prestations et tarifs')}</h2><div class="svcs">${svcCards}</div></div></section>
  <section class="band alt"><div class="wrap two">${booking}
    <div class="card" id="devis"><h3>${t('Demander un devis')}</h3><form id="quote" data-base="${esc(base)}" novalidate><div class="g2"><div><label for="q-name">${t('Nom')}</label><input id="q-name" name="name" required></div><div><label for="q-phone">${t('Téléphone')}</label><input id="q-phone" name="phone" type="tel" required></div></div>
    <label for="q-email">${t('E-mail')}</label><input id="q-email" name="email" type="email"><label for="q-obj">${esc(tn.obj_label)}</label><input id="q-obj" name="obj"><label for="q-svc">${t('Prestation')}</label><select id="q-svc" name="service">${tn.services.map((s) => `<option>${esc(s.name)}</option>`).join('')}<option>${t('Autre')}</option></select>
    <label for="q-msg">${t('Votre demande')}</label><textarea id="q-msg" name="message" maxlength="2000"></textarea><div class="err" id="q-err" role="alert"></div><button class="btn wide" type="submit">${t('Envoyer la demande')}</button><div id="q-ok" role="status"></div>${NOTICE(tn)}</form></div></div></section>
  <section class="band"><div class="wrap grid3"><div><h3>${t('Adresse')}</h3><p class="muted">${esc(tn.address || tn.city)}</p></div><div><h3>${t('Horaires')}</h3><table class="hours">${hours}</table><p class="note">${t('Heure locale : {z}', { z: esc(tn.tz) })}</p></div><div><h3>${t('Contact')}</h3><p class="muted">${esc(phoneFmt(tn.phone))}</p>${wa ? `<a class="btn wa" href="${esc(wa)}" rel="noopener">${t('Écrire sur WhatsApp')}</a>` : ''}</div></div></section>
  <footer class="foot"><div class="wrap row"><span>${esc(tn.name)}</span><span><a href="${esc(config.baseUrl)}/confidentialite">${t('Confidentialité')}</a> · <a href="${esc(config.baseUrl)}/mentions-legales">${t('Mentions légales')}</a> · ${t('Site réalisé avec')} <a href="${esc(config.baseUrl)}/${mode === 'live' ? `?ref=${encodeURIComponent(tn.slug)}` : ''}">ClientDirect Pro</a></span></div></footer>
  <script type="application/json" id="i18n">${siteStrings()}</script><script src="/static/site.js" defer></script>`, { brand: tn.color, bodyClass: 'site', head });
}
export const pausedPage = (tn) => messagePage(tn ? tn.name : t('Site indisponible'), t('Ce site est momentanément indisponible. Contactez directement le professionnel.'));

// ---------- espace pro ----------
export function proShell(tn, user, csrf, active, body, { example = false } = {}) {
  const nav = [['/pro', 'Demandes', 'home'], ['/pro/reglages', 'Réglages', 'set'], ['/pro/abonnement', 'Abonnement', 'bill'], ['/pro/aide', 'Aide', 'help']].map(([h, l, k]) => `<a href="${example ? '#' : h}" ${active === k ? 'aria-current="page"' : ''}>${t(l)}</a>`).join('');
  const siteUrl = example ? `${config.baseUrl}/exemple/${tn.tpl}` : `${config.baseUrl}/s/${tn.slug}`;
  const ex = example ? `<div class="demo-bar"><b>${t('Espace professionnel d’exemple')}</b> · ${t('Données fictives, boutons désactivés.')} <a class="btn sm blue" href="/inscription">${t('Créer mon site')}</a></div>` : '';
  return layout(`${t('Espace pro')} · ${tn.name}`, `${ex}<header class="appbar"><div class="wrap row"><b class="logo">ClientDirect Pro</b><nav>${nav}</nav>${example ? '' : `<form method="post" action="/deconnexion">${csrfField(csrf)}<button class="linkbtn" type="submit">${t('Déconnexion')}</button></form>`}</div></header>
  <main class="band app"><div class="wrap"><div class="row top"><div><h1>${esc(tn.name)}</h1><p class="muted">${t('Votre site :')} <a href="${esc(siteUrl)}" target="_blank" rel="noopener">${esc(siteUrl)}</a> · <span class="pill st-${tn.status}">${st(tn.status)}</span>${tn.status === 'trial' && tn.trial_ends_at ? ` ${t('jusqu’au {d}', { d: fmtDate(tn.trial_ends_at) })}` : ''}</p></div></div>${!example && !user.email_verified ? `<div class="flash warn">${t('Confirmez votre adresse e-mail grâce au lien reçu pour sécuriser votre compte.')}</div>` : ''}${body}</div></main>`, { bodyClass: 'appbody' });
}
const A_LABEL = { pending: 'À confirmer', confirmed: 'Confirmé', done: 'Terminé', refused: 'Refusé', canceled: 'Annulé' };
export function proDashboard(tn, user, csrf, { appts, quotes, stats, msg, perf = null, curve = [], example = false, askFeedback = false, referral = null }) {
  const m2 = (v) => money(v, tn.currency || 'EUR', locale(currentLang(), tn.country));
  const act = (a) => {
    const f = (s, label, cls = '') => `<form method="post" action="/pro/rdv/${a.id}/statut" class="inline">${csrfField(csrf)}<input type="hidden" name="status" value="${s}"><button class="btn sm ${cls}" type="submit" ${example ? 'disabled' : ''}>${t(label)}</button></form>`;
    if (a.status === 'pending') return f('confirmed', 'Confirmer') + f('refused', 'Refuser', 'ghost');
    if (a.status === 'confirmed') return f('done', 'Terminé', 'ghost') + f('canceled', 'Annuler', 'ghost');
    return '';
  };
  const rows = appts.length ? appts.map((a) => `<div class="req"><div class="rh"><span class="pill st-${a.status}">${t(A_LABEL[a.status])}</span><b>${esc(a.customer_name)}</b><span>${esc(fmtDay(a.date))} · ${esc(fmtTime(a.time))}</span><span class="muted">${esc(a.service_name)} · ${esc(a.staff_name)}${a.source === 'assistant' ? ` · ${t('via l’assistant')}` : ''}</span></div><div class="muted">${esc(phoneFmt(a.customer_phone))}${a.customer_email ? ' · ' + esc(a.customer_email) : ''}</div><div class="acts">${act(a)}<a class="btn sm wa" href="${example ? '#' : `https://wa.me/${esc(a.customer_phone)}`}" rel="noopener">WhatsApp</a></div></div>`).join('') : `<p class="muted">${t('Aucun rendez-vous à venir.')}</p>`;
  const qrows = quotes.length ? quotes.map((q) => `<div class="req"><div class="rh"><span class="pill ${q.status === 'new' ? 'st-pending' : 'st-done'}">${q.status === 'new' ? t('À traiter') : q.status === 'handled' ? t('Traité') : t('Refusé')}</span><b>${esc(q.customer_name)}</b><span class="muted">${esc(q.service)}${q.obj ? ' · ' + esc(q.obj) : ''}</span></div>${q.message ? `<p>« ${esc(q.message)} »</p>` : ''}<div class="muted">${esc(phoneFmt(q.customer_phone))}${q.customer_email ? ' · ' + esc(q.customer_email) : ''}</div><div class="acts">${q.status === 'new' ? `<form method="post" action="/pro/devis/${q.id}/statut" class="inline">${csrfField(csrf)}<input type="hidden" name="status" value="handled"><button class="btn sm" type="submit" ${example ? 'disabled' : ''}>${t('Marquer traité')}</button></form>` : ''}<a class="btn sm wa" href="${example ? '#' : `https://wa.me/${esc(q.customer_phone)}`}" rel="noopener">WhatsApp</a></div></div>`).join('') : `<p class="muted">${t('Aucune demande de devis.')}</p>`;
  return proShell(tn, user, csrf, 'home', `${flash(msg)}<div class="kpis"><div class="k"><strong>${stats.pending}</strong><span>${t('rendez-vous à confirmer')}</span></div><div class="k"><strong>${stats.upcoming}</strong><span>${t('rendez-vous à venir')}</span></div><div class="k"><strong>${stats.quotes}</strong><span>${t('devis à traiter')}</span></div><div class="k"><strong>${m2(stats.revenue)}</strong><span>${t('prévu (rendez-vous confirmés)')}</span></div></div>
  ${perf ? perfCard(perf, curve, m2) : ''}<div class="two"><section class="card"><h2>${t('Rendez-vous')}</h2>${rows}</section><section class="card"><h2>${t('Demandes de devis')}</h2>${qrows}</section></div>${referral && !example ? referralCard(tn, referral) : ''}${askFeedback && !example ? feedbackCard(csrf) : ''}`, { example });
}
function referralCard(tn, r) {
  const link = `${config.baseUrl}/?ref=${encodeURIComponent(tn.slug)}`;
  return `<section class="card" id="parrainage"><h2>${t('Parrainez un professionnel, gagnez un mois')}</h2><p>${t('Quand un professionnel inscrit avec votre lien paie son abonnement, vous recevez chacun un mois offert, déduit automatiquement de votre prochaine facture.')}</p>
  <label for="ref-link">${t('Votre lien de parrainage')}</label><input id="ref-link" readonly value="${esc(link)}">
  <p class="muted small">${t('{a} inscrit(s) avec votre lien · {b} abonné(s) · {c} mois offert(s).', { a: r.referred, b: r.paying, c: r.months })} ${t('Le mois offert est validé 30 jours après le premier paiement de votre filleul, sans remboursement entre-temps. 12 mois offerts au maximum par an.')}</p></section>`;
}
function feedbackCard(csrf) {
  const opts = [1, 2, 3, 4, 5].map((n) => `<label class="ck"><input type="radio" name="score" value="${n}" required> ${n}</label>`).join('');
  return `<section class="card" id="avis"><h2>${t('Votre avis compte')}</h2><p class="muted">${t('De 1 à 5, ClientDirect Pro vous est-il utile ? Une phrase suffit pour nous dire quoi améliorer.')}</p><form method="post" action="/pro/avis">${csrfField(csrf)}<div class="row gap">${opts}</div><label for="fb-c">${t('Votre commentaire (facultatif)')}</label><textarea id="fb-c" name="comment" maxlength="1000" rows="3"></textarea><button class="btn sm" type="submit">${t('Envoyer mon avis')}</button></form></section>`;
}
function perfCard(p, curve, m2) {
  const max = Math.max(1, ...curve.map((d) => d.views));
  const bars = curve.map((d) => `<span class="bar" style="height:${Math.round((d.views / max) * 100)}%" title="${esc(fmtDay(d.day))} : ${d.views} / ${d.requests}"><i style="height:${d.views ? Math.round((d.requests / d.views) * 100) : 0}%"></i></span>`).join('');
  return `<section class="card" id="perf"><h2>${t('Ce que votre site vous a apporté (30 derniers jours)')}</h2><div class="kpis"><div class="k"><strong>${p.views}</strong><span>${t('visites')}</span></div><div class="k"><strong>${p.requests}</strong><span>${t('demandes reçues (rendez-vous, devis, WhatsApp)')}</span></div><div class="k"><strong>${p.confirmed}</strong><span>${t('rendez-vous honorés ou confirmés')}</span></div><div class="k"><strong>${m2(p.value)}</strong><span>${t('de prestations réservées')}</span></div></div>
  <p class="muted">${t('Détail : {b} réservation(s), {q} devis, {w} contact(s) WhatsApp, {c} question(s) à l’assistant · {r} % des visiteurs vous ont contacté.', { b: p.bookings, q: p.quotes, w: p.wa_clicks, c: p.chats, r: p.conversion })}</p><div class="spark" aria-hidden="true">${bars}</div></section>`;
}
export function proSettings(tn, user, csrf, { errors = [], saved = false, domainMsg = '', dnsTarget = '' }) {
  const lang = currentLang();
  const svc = tn.services.map((s, i) => `<tr><td><input type="hidden" name="svc_id_${i}" value="${s.id}"><input name="svc_name_${i}" value="${esc(s.name)}" aria-label="${t('Prestation')}" maxlength="80"></td><td><input name="svc_price_${i}" value="${esc(s.price)}" inputmode="decimal" aria-label="${t('Prix')}" class="n"></td><td><input name="svc_dur_${i}" value="${s.dur}" type="number" step="15" min="15" aria-label="${t('Durée')}" class="n"></td><td><input name="svc_desc_${i}" value="${esc(s.descr)}" aria-label="${t('Description')}" maxlength="200"></td></tr>`).join('');
  const n = tn.services.length;
  const empty = [0, 1].map((k) => `<tr><td><input name="svc_name_${n + k}" placeholder="${t('Nouvelle prestation')}" aria-label="${t('Nouvelle prestation')}" maxlength="80"></td><td><input name="svc_price_${n + k}" value="0" class="n" aria-label="${t('Prix')}"></td><td><input name="svc_dur_${n + k}" value="60" type="number" step="15" min="15" class="n" aria-label="${t('Durée')}"></td><td><input name="svc_desc_${n + k}" aria-label="${t('Description')}" maxlength="200"></td></tr>`).join('');
  const staff = tn.staff.map((s, i) => `<input type="hidden" name="staff_id_${i}" value="${s.id}"><input name="staff_name_${i}" value="${esc(s.name)}" aria-label="${t('Poste')}" maxlength="60">`).join('') + `<input name="staff_name_${tn.staff.length}" placeholder="${t('Ajouter un poste')}" aria-label="${t('Nouveau poste')}" maxlength="60">`;
  const hours = [1, 2, 3, 4, 5, 6, 0].map((d) => { const h = tn.hours[d]; return `<div class="hrow"><label class="ck"><input type="checkbox" name="open_${d}" ${h ? 'checked' : ''}> ${dayName(d)}</label><input type="time" name="from_${d}" value="${h ? h[0] : '08:00'}" aria-label="${t('Ouverture')} ${dayName(d)}"><input type="time" name="to_${d}" value="${h ? h[1] : '17:00'}" aria-label="${t('Fermeture')} ${dayName(d)}"></div>`; }).join('');
  const cOpts = Object.keys(COUNTRIES).map((k) => `<option value="${k}" ${tn.country === k ? 'selected' : ''}>${esc(countryName(k, lang))}${COUNTRIES[k].dial ? ` (+${COUNTRIES[k].dial})` : ''}</option>`).join('');
  const tzOpts = ALL_TZ.map((z) => `<option ${tn.tz === z ? 'selected' : ''}>${esc(z)}</option>`).join('');
  return proShell(tn, user, csrf, 'set', `${saved ? flash(t('Réglages enregistrés. Votre site est à jour.')) : ''}${errs(errors)}<form method="post" action="/pro/reglages" class="stack-form">${csrfField(csrf)}
  <section class="card"><h2>${t('Prestations et tarifs')}</h2><p class="muted">${t('Pour retirer une prestation, videz son nom.')}</p><div class="scroll"><table class="etab"><thead><tr><th>${t('Prestation')}</th><th>${t('Prix')} (${esc(tn.currency)})</th><th>${t('Durée min')}</th><th>${t('Description')}</th></tr></thead><tbody>${svc}${empty}</tbody></table></div></section>
  <div class="two"><section class="card"><h2>${t('Horaires')}</h2>${hours}<label class="ck"><input type="checkbox" name="auto_confirm" ${tn.auto_confirm ? 'checked' : ''}> ${t('Confirmer automatiquement les rendez-vous')}</label></section>
  <section class="card"><h2>${t('Postes ou employés')}</h2><p class="muted">${t('Un rendez-vous à la fois par poste.')}</p><div class="staff">${staff}</div></section></div>
  <section class="card"><h2>${t('Informations')}</h2><div class="g2"><div><label for="name">${t('Nom')}</label><input id="name" name="name" value="${esc(tn.name)}" maxlength="80"></div><div><label for="phone">${t('Téléphone WhatsApp')}</label><input id="phone" name="phone" type="tel" value="${esc(tn.phone ? '+' + tn.phone : '')}"></div></div>
  <div class="g2"><div><label for="country">${t('Pays')}</label><select id="country" name="country">${cOpts}</select></div><div><label for="tz">${t('Fuseau horaire')}</label><select id="tz" name="tz">${tzOpts}</select></div></div>
  <div class="g2"><div><label for="currency">${t('Devise des prix')}</label><select id="currency" name="currency">${CURRENCIES.map((c) => `<option ${tn.currency === c ? 'selected' : ''}>${c}</option>`).join('')}</select></div><div><label for="lang">${t('Langue du site')}</label><select id="lang" name="lang">${Object.entries(LANGS).map(([k, v]) => `<option value="${k}" ${tn.lang === k ? 'selected' : ''}>${v}</option>`).join('')}</select></div></div>
  <div class="g2"><div><label for="city">${t('Ville')}</label><input id="city" name="city" value="${esc(tn.city)}" maxlength="60"></div><div><label for="color">${t('Couleur')}</label><input id="color" name="color" type="color" value="${esc(tn.color)}"></div></div>
  <label for="address">${t('Adresse')}</label><input id="address" name="address" value="${esc(tn.address)}" maxlength="160"><label for="lead">${t('Phrase d’accueil')}</label><textarea id="lead" name="lead" maxlength="400">${esc(tn.lead)}</textarea>
  <label for="faq">${t('Informations pour l’assistant (paiement, conditions, accès…)')}</label><textarea id="faq" name="faq" maxlength="1500">${esc(tn.faq)}</textarea></section>
  <button class="btn red" type="submit">${t('Enregistrer et mettre le site à jour')}</button></form>
  <section class="card" id="domaine"><h2>${t('Votre propre nom de domaine')}</h2>${planHas(tn.plan, 'rdv') ? `${domainMsg ? flash(domainMsg) : ''}<p class="muted">${t('Utilisez une adresse à votre nom (ex. www.mon-garage.fr) au lieu de l’adresse ClientDirect Pro. Le certificat de sécurité (https) est installé automatiquement.')}</p>
  <form method="post" action="/pro/domaine" class="row gap">${csrfField(csrf)}<input name="domain" placeholder="www.mon-entreprise.fr" value="${esc(tn.custom_domain || '')}" aria-label="${t('Nom de domaine')}" maxlength="253"><button class="btn sm" type="submit">${t('Enregistrer')}</button></form>
  ${tn.custom_domain ? `<p>${t('État :')} <span class="pill ${tn.domain_status === 'verified' ? 'st-active' : 'st-pending'}">${tn.domain_status === 'verified' ? t('Actif') : tn.domain_status === 'manual' ? t('Activation par notre équipe') : t('En attente de votre réglage DNS')}</span></p>
  ${tn.domain_status === 'verified' ? '' : `<p>${t('Chez votre fournisseur de domaine (OVH, Gandi, GoDaddy…), créez cet enregistrement :')}</p><table class="list"><tr><th>${t('Type')}</th><th>${t('Nom')}</th><th>${t('Valeur')}</th></tr><tr><td>CNAME</td><td>${esc(tn.custom_domain.split('.')[0])}</td><td class="mono">${esc(dnsTarget || t('communiquée par e-mail'))}</td></tr></table><p class="note">${t('La vérification est automatique (quelques minutes à 24 h). Utilisez de préférence une adresse en « www. ».')}</p>`}` : ''}` : `<p class="muted">${t('Disponible avec les formules Pro et Premium.')}</p>`}</section>
  <section class="card" id="compte"><h2>${t('Vos données')}</h2><p class="muted">${t('Téléchargez toutes les données de votre entreprise (prestations, rendez-vous, devis, factures, statistiques) ou supprimez définitivement votre compte.')}</p>
  <p><a class="btn sm ghost" href="/pro/donnees/export">${t('Télécharger mes données (JSON)')}</a></p>
  <details><summary>${t('Supprimer mon compte')}</summary><form method="post" action="/pro/compte/supprimer">${csrfField(csrf)}<p>${t('Votre site sera supprimé immédiatement, ainsi que les rendez-vous et devis. Les factures sont conservées 10 ans (obligation légale). Pensez à résilier votre abonnement avant.')}</p><label for="del-pw">${t('Mot de passe pour confirmer')}</label><input id="del-pw" name="password" type="password" autocomplete="current-password" required><button class="btn red sm" type="submit">${t('Supprimer définitivement')}</button></form></details></section>`);
}
export function proBilling(tn, user, csrf, { configured, open = true, msg, invoices }) {
  const m2 = (cents, cur) => money(cents / 100, (cur || tn.currency || 'EUR').toUpperCase(), locale(currentLang(), tn.country));
  const inv = invoices.length ? `<table class="list"><thead><tr><th>${t('Date')}</th><th class="num">${t('Montant')}</th><th>${t('Statut')}</th></tr></thead><tbody>${invoices.map((i) => `<tr><td>${fmtDate(i.paid_at || i.created_at)}</td><td class="num">${m2(i.amount_cents, i.currency)}</td><td>${i.status === 'paid' ? t('Payée') : esc(i.status)}</td></tr>`).join('')}</tbody></table>` : `<p class="muted">${t('Aucune facture pour l’instant.')}</p>`;
  const notice = !open ? `<div class="flash warn">${t('Les abonnements payants ne sont pas encore ouverts dans votre pays. Votre site reste disponible : nous vous prévenons dès l’ouverture.')}</div>` : !configured ? `<div class="flash warn">${t('Le paiement en ligne n’est pas encore activé sur cette plateforme.')}</div>` : '';
  return proShell(tn, user, csrf, 'bill', `${flash(msg)}${notice}
  <section class="card"><h2>${t('Votre formule : {p}', { p: planName(tn.plan) })}</h2><p>${t('Statut :')} <span class="pill st-${tn.status}">${st(tn.status)}</span>${tn.current_period_end ? ` · ${t('prochaine échéance le {d}', { d: fmtDate(tn.current_period_end) })}` : ''}</p>
  ${tn.stripe_customer ? `<form method="post" action="/pro/abonnement/portail">${csrfField(csrf)}<button class="btn" type="submit">${t('Gérer mon abonnement (carte, factures, résiliation)')}</button></form>` : ''}</section>
  ${tn.status === 'active' ? '' : planCards(tn.currency || 'EUR', { action: '/pro/abonnement/checkout', csrf, current: tn.plan, disabled: !configured || !open })}<section class="card"><h2>${t('Factures')}</h2>${inv}</section>`);
}
export function proHelp(tn, user, csrf, { q = '', answer = null, tickets = [], msg }) {
  return proShell(tn, user, csrf, 'help', `${flash(msg)}<div class="two"><section class="card"><h2>${t('Posez votre question')}</h2><form method="post" action="/pro/aide/question">${csrfField(csrf)}<label for="q">${t('Votre question')}</label><textarea id="q" name="q" maxlength="800" required>${esc(q)}</textarea><button class="btn" type="submit">${t('Obtenir une réponse')}</button></form>
  ${answer ? `<div class="answer"><p>${esc(answer.text)}</p>${answer.articles.length ? `<p class="muted">${t('Fiches liées :')} ${answer.articles.map((a) => esc(t(a.title))).join(', ')}</p>` : ''}<form method="post" action="/pro/aide/ticket">${csrfField(csrf)}<input type="hidden" name="subject" value="${esc(q.slice(0, 120))}"><input type="hidden" name="body" value="${esc(q)}"><button class="btn ghost sm" type="submit">${t('Ce n’est pas résolu : ouvrir un ticket')}</button></form></div>` : ''}</section>
  <section class="card"><h2>${t('Fiches d’aide')}</h2>${KB.map((a) => `<details><summary>${esc(t(a.title))}</summary><p>${esc(t(a.body))}</p></details>`).join('')}</section></div>
  <section class="card"><h2>${t('Mes tickets')}</h2>${tickets.length ? tickets.map((tk) => `<div class="req"><div class="rh"><span class="pill">${tk.status === 'open' ? t('En attente') : tk.status === 'answered' ? t('Répondu') : t('Fermé')}</span><b>${esc(tk.subject)}</b></div>${tk.messages.map((m) => `<p class="${m.author === 'client' ? '' : 'muted'}"><b>${m.author === 'client' ? t('Vous') : t('Assistance')} :</b> ${esc(m.body)}</p>`).join('')}</div>`).join('') : `<p class="muted">${t('Aucun ticket.')}</p>`}</section>`);
}

